# -*- coding: utf-8 -*-
import json
T=json.load(open('/home/claude/jer/txt/46.json'))
def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=2,star=2,lit=L(1,2),
key=[('列國','H1471','hagoyim','列國、列邦'),('法老尼哥','H6549','paroh nekho','法老尼哥'),('迦基米施','H3751','karkemish','迦基米施'),('幼發拉底河','H6578','perat','幼發拉底河'),('打敗','H5221','hikkah','擊打、打敗'),('第四年','H7243','revit','第四（年）')],
gram=['**列國**：原文是 hagoyim，「各國、列邦」。**四十六至五十一章，是耶利米書裡「論列國的話」，一共十個國家與地區。**','**第四年**：「約雅敬第四年」，與三十六章1節、四十五章1節，同一個年份。**這是整卷書裡，一個很重要的時間座標。**'],
exp=['四十六章，是一個新的段落。**一節說：耶和華論列國的話，臨到先知耶利米。****從這裡開始，到五十一章，是耶利米書裡「論列國」的一大段：埃及、非利士、摩押、亞捫、以東、大馬士革、基達、夏瑣、以攔、巴比倫。****在這之前，耶利米書的大部分，是對猶大說話；現在，鏡頭拉開，神的話，轉向列國。**','這是一個很重要的提醒：**耶利米一章5節，神立他「作列國的先知」。****到了這裡，這個召命，才完整地顯明。****神不只是猶大的神，也是列國的主。****祂審判猶大，也審判埃及；祂掌管耶路撒冷，也掌管尼羅河。**','二節，給了這篇預言的時間與地點：**論到關乎埃及王法老尼哥的軍隊，這軍隊安營在幼發拉底河邊的迦基米施，是巴比倫王尼布甲尼撒，在猶大王約西亞的兒子約雅敬第四年所打敗的。****請你留意，這個年份，與三十六章、四十五章，是同一年。****我們不用推算這一年是西元前哪一年，也不用把它變成歷史課；我們只看見：在同一年，巴錄寫書卷，埃及被打敗。**','我們要先說清楚一件事，免得這一章被讀成歷史報告：**這一段的重點，不是記錄一場戰役的經過，而是讓人看見：在那個世界舞台上，有一位神，在掌管。****埃及是當時最大的力量之一，猶大人正在想：要不要倚靠它。****神的話，先把這個「倚靠」，拆開來。**']),
dict(a=3,z=6,star=3,lit=L(3,6),
key=[('盾牌','H4043','magen','盾牌'),('驚惶','H2844','khittim','驚惶、嚇破膽'),('勇士','H1368','gibborim','勇士'),('逃跑','H5127','nasu','逃跑'),('北方','H6828','tsafonah','北方'),('絆跌','H3782','kashelu','絆跌、失腳')],
gram=['**驚惶**：「我為何看見他們驚惶轉身退後呢？」**這是一個問句，而且是神自己在問，帶著很深的感嘆。**','**北方**：原文 tsafon。**在耶利米書，「北方」是災禍的方向（一14；四6）；這裡，埃及的軍隊，也在北方的幼發拉底河邊絆跌。**'],
exp=['三到四節，是一連串的軍事口令：**你們要預備大小盾牌，往前上陣。你們套上車，騎上馬！頂盔站立，磨槍貫甲！****這是很有氣勢的一段：盾牌、戰車、戰馬、頭盔、長槍、盔甲。****像是一幅出征的畫面，一個接一個，整整齊齊。**','可是，五節，畫面忽然翻轉：**我為何看見他們驚惶轉身退後呢？他們的勇士打敗了，急忙逃跑，並不回頭。****請你注意：說這句話的，是神。****祂說：我看見。****前面是響亮的號令，後面是驚惶的逃跑，中間沒有過程，只有一個很大的落差。**','六節，補上一個很具體的畫面：**不要容快跑的逃避，不要容勇士逃脫；他們在北方幼發拉底河邊絆跌仆倒。****「絆跌仆倒」，是一個很熟悉的詞，耶利米書裡，神一再用它描寫：人以為自己很穩，卻在不知不覺之中，失腳。****我們不用在這裡，替這場戰事補上細節；我們只看見：再強的軍隊，在神的話面前，也會絆跌。**']),
dict(a=7,z=9,star=2,lit=L(7,9),
key=[('尼羅河','H2975','keyor','尼羅河'),('漲發','H5927','yaaleh','上升、漲發'),('翻騰','H1607','yitgashu','翻騰'),('遮蓋','H3680','akhasseh','遮蓋'),('毀滅','H6','avidah','毀滅'),('古實人','H3568','kush','古實人'),('路德','H3866','ludim','路德族')],
gram=['**尼羅河**：原文 yeor，專指尼羅河。**埃及的命脈，每年漲發，帶來肥沃；這個比喻，把埃及的自誇，用它最熟悉的畫面說出來。**'],
exp=['七到八節，用一個畫面，描寫埃及的氣勢：**像尼羅河漲發，像江河之水翻騰的是誰呢？埃及像尼羅河漲發，像江河的水翻騰。他說：我要漲發遮蓋遍地；我要毀滅城邑和其中的居民。****請你留意：這裡的「他說」。****是埃及自己說：我要遮蓋遍地。****這不是神的話，是埃及的口氣。**','尼羅河，是埃及人最熟悉的河；它每年漲發，帶來水、帶來肥沃。**埃及，用它自己最引以為傲的畫面，來形容自己：我是漲發的大水，我要淹沒遍地。****可是，我們很快就會看見：這個畫面，在下一個段落，將被翻轉。****在耶利米書四十七章，「水從北方漲起」，是另一種水。**','九節，列出埃及的軍隊：**馬匹上去吧！車輛急行吧！勇士，就是手拿盾牌的古實人和弗人，並拉弓的路德族，都出去吧！****請你看這個名單：古實人、弗人、路德族。****埃及的軍隊，不只是埃及人，也包括了從南方、西方招來的外族勇士。****這是一個很大的聯軍，聲勢浩大，這是他們「漲發」的樣子。**']),
dict(a=10,z=12,star=3,lit=L(10,12),
key=[('報仇','H5360','neqamah','報仇、伸冤'),('刀劍','H2719','kherev','刀劍'),('獻祭','H2077','zevakh','祭'),('乳香','H6875','tseri','乳香（藥膏）'),('良藥','H7499','refuot','藥物、醫治'),('徒然','H7723','lashav','徒然、虛空'),('羞辱','H7036','qalon','羞辱')],
gram=['**獻祭**：「在北方幼發拉底河邊有獻祭的事」。**這是一個很大膽的比喻：那一場戰事，在神的眼中，像一場獻祭。****我們不替這個比喻，加上更多解釋。**','**乳香**：基列的乳香，是古代很有名的藥膏（八22）。**「上基列取乳香去」，是一句很諷刺的話：連最好的藥，也治不好。**'],
exp=['十節，神說出這一天，在祂眼中的意思：**那日是主萬軍之耶和華報仇的日子，要向敵人報仇。刀劍必吞吃得飽，飲血飲足；因為主萬軍之耶和華在北方幼發拉底河邊有獻祭的事。****這是很重的句子。****我們不替它加上輕鬆的解釋，也不拿它去套任何今天的戰爭；它的位置，是神對那一場戰事，在那一個時刻，所說的話。**','十一節，一個很有畫面感的諷刺：**埃及的民哪，可以上基列取乳香去；你雖多服良藥，總是徒然，不得治好。****基列的乳香，是古代有名的藥膏；耶利米書八22，耶利米問過：「在基列豈沒有乳香嗎？」現在，這個問句，轉到了埃及身上。****意思是：連最好的藥，也治不好這個傷。**','十二節：**列國聽見你的羞辱，遍地滿了你的哀聲；勇士與勇士彼此相碰，一齊跌倒。****請你看這個畫面：不是被別人推倒，是「彼此相碰」，一齊跌倒。****勇士撞上勇士，每一個人都想逃，卻擠在一起。****這是一個很真實的潰敗畫面。**','這一段，有一個重要的提醒：**四十六章的審判，是一個很具體的歷史場景，卻不是一份歷史報告。****我們不為它加上戰役的細節，不推算日子；我們讀的，是神對自己所掌管的列國，說的話：你們所倚靠的，無論多強，都不是最後的。**']),
dict(a=13,z=17,star=2,lit=L(13,17),
key=[('傳揚','H5046','haggidu','傳揚、宣告'),('密奪','H4024','migdol','密奪'),('挪弗','H5297','nof','挪弗'),('答比匿','H8471','takhpankhes','答比匿'),('驅逐','H1920','hadafo','推倒、驅逐'),('欺壓','H3238','hayyonah','欺壓'),('所定的時候','H4150','hammoed','所定的時候')],
gram=['**聲音**：「法老不過是個聲音」，原文 shaon，是「喧嚷、吵鬧」。**一個很大的聲勢，卻是空的。**'],
exp=['十三節，是第二個段落的開始：**耶和華對先知耶利米所說的話，論到巴比倫王尼布甲尼撒要來攻擊埃及地。****請你注意：到這裡，預言，從迦基米施的戰場，移到了埃及本土。****十四節，神列出地名：密奪、挪弗、答比匿。****這三個地名，我們很熟悉：四十四章1節，猶大人，正住在這些地方。**','這是一個很有意思的連結：**四十四章，神的話臨到住在密奪、答比匿、挪弗、巴忒羅的猶大人；四十六章，這些同樣的地名，成為神對埃及的警告的地點。****猶大人逃到埃及，以為找到了避難所；神說，這個避難所本身，也有審判要來。****這不是兩篇孤立的預言，而是同一個信息，從兩個方向，說出來。**','十五到十六節：**你的壯士為何被沖去呢？他們站立不住；因為耶和華驅逐他們，使多人絆跌；他們也彼此撞倒，說：起來吧！我們再往本民本地去，好躲避欺壓的刀劍。****請你留意：「耶和華驅逐他們」。****這句話，把一場軍事潰敗，放在神的手中；也讓我們看見：那些逃兵，想要回到自己的本地，卻是在逃。**','十七節，是這一段，最有名的一句：**他們在那裡喊叫說：埃及王法老不過是個聲音；他已錯過所定的時候了。****法老，這位埃及的王，在人眼中是一個很大的名；在神的話裡，是「一個聲音」，聲勢很大，卻是空的。****「所定的時候」，是一個很有分量的詞：有一個時間，是被定下的，法老錯過了。****我們不為這個詞，補上確切的日子；我們只看見：神所定的，比人的氣勢更真實。**']),
dict(a=18,z=21,star=3,lit=L(18,21),
key=[('永生','H2416','khai','活著、永生'),('他泊','H8396','tavor','他泊山'),('迦密','H3760','karmel','迦密山'),('擄去','H1473','golah','被擄'),('荒場','H8047','shammah','荒涼'),('雇勇','H7916','sekhirehah','雇來的兵'),('追討','H6486','pequddatam','追討、察訪')],
gram=['**永生**：「我指著我的永生起誓」，原文是 khai-ani，「我是活的」。**這是神最重的誓言格式。****神拿自己的生命，保證這句話。**','**母牛犢**：「埃及是肥美的母牛犢」。**肥美的牛犢，養得好、長得壯，卻也是最容易被宰殺的。**'],
exp=['十八節，神用一個很重的誓言開始：**君王，名為萬軍之耶和華的說：我指著我的永生起誓：尼布甲尼撒來的勢派，必像他泊在眾山之中，像迦密在海邊一樣。****請你看這個誓言：「我指著我的永生起誓」。****在整個聖經裡，神的誓言，都是最重的。****祂說：我是永遠活著的，我的話，就像我的生命一樣可靠。**','他泊與迦密，是以色列地兩座顯眼的山：**一座在眾山之中突出，一座在海邊矗立。****這個比喻的意思，是說：這個勢派，一出現，就讓人無法忽視。****我們不為這個比喻，加上確切的描寫；我們只看見：神的話，把這場即將來到的事，放在人人都看得見的位置。**','十九節：**住在埃及的民哪，要預備擄去時所用的物件；因為挪弗必成為荒場，且被燒毀，無人居住。****請你注意「預備擄去時所用的物件」，這是很具體的警告：收拾行李的時候到了。****二十節：埃及是肥美的母牛犢；但出於北方的毀滅來到了！來到了！****二十一節：其中的雇勇好像圈裡的肥牛犢，他們轉身退後，一齊逃跑，站立不住。**','這一連串，是一個很誠實的畫面：**埃及，是肥美的母牛犢，是被養得很好的一個國家；可是，被養得好，不等於不會被宰。****就連那些雇來的兵，也像圈裡的肥牛犢，被餵養、被依靠，在遭難的日子，卻轉身逃跑。****神的話，一再把人們所倚靠的，拆開來給我們看：不是因為它不強大，而是因為，它不是神。**']),
dict(a=22,z=24,star=2,lit=L(22,24),
key=[('蛇','H5175','nakhash','蛇'),('斧子','H7134','qardummot','斧子'),('砍伐','H3772','karetu','砍伐'),('蝗蟲','H697','arbeh','蝗蟲'),('蒙羞','H3001','hevishah','蒙羞'),('北方','H6828','tsafon','北方')],
gram=['**蛇行**：「其中的聲音好像蛇行一樣」。**這是一個很安靜的畫面：一個龐大的國家，到最後，只剩下嘶嘶的聲音。**'],
exp=['二十二節：**其中的聲音好像蛇行一樣。敵人要成隊而來，如砍伐樹木的手拿斧子攻擊他。****請你看這個畫面：先是蛇行，一種很小、很低、很快的聲音；然後是成隊的敵人，像砍樹的人，拿著斧子。****埃及，從一個龐大的聲勢，變成了一棵被砍伐的樹。**','二十三節：**耶和華說：埃及的樹林雖然不能尋察，敵人卻要砍伐，因他們多於蝗蟲，不可勝數。****請你留意「不能尋察」：埃及的樹林，密到無法探測；這是用來形容埃及的龐大與深不可測。****可是，敵人像蝗蟲，不可勝數。****再大的樹林，也擋不住無數的斧子。**','二十四節，簡短地作結：**埃及的民必然蒙羞，必交在北方人的手中。****這一段，沒有解釋，沒有安慰，只有一個很清楚的結論。****我們不為這個結論，加上時間表，也不把它套用到今日任何一個國家；我們只讀神對那個國家、在那個時刻，說的話。**']),
dict(a=25,z=26,star=3,lit=L(25,26),
key=[('亞捫','H528','amon','亞捫（挪的神）'),('刑罰','H6485','poked','察看、刑罰'),('倚靠','H982','habotkhim','倚靠'),('尋索','H1245','mevaqshei','尋找、追索'),('居住','H7931','tishkon','居住'),('神','H430','elohehah','神、神明')],
gram=['**居住**：「以後埃及必再有人居住，與從前一樣」。**這是一個令人驚訝的應許：連埃及，也有「以後」。**'],
exp=['二十五節，神的話，從「埃及」轉到了「埃及的神」：**萬軍之耶和華以色列的神說：我必刑罰挪的亞捫和法老，並埃及與埃及的神，以及君王，也必刑罰法老和倚靠他的人。****「挪的亞捫」，是底比斯的神。****請你看，神的審判，不只是軍隊，也包括他們的神、他們的王，和所有倚靠法老的人。**','這裡，有一個很深的提醒：**「倚靠他的人」。****在四十二至四十四章，猶大人，是倚靠埃及的人；現在，這裡說：神也要刑罰「倚靠他的人」。****這句話，是對所有倚靠埃及的人說的，包括那些逃到埃及的猶大人。****神很清楚地告訴他們：你們倚靠的，不是避難所。**','二十六節，有一個令人驚訝的轉折：**我要將他們交付尋索其命之人的手和巴比倫王尼布甲尼撒與他臣僕的手；以後埃及必再有人居住，與從前一樣。這是耶和華說的。****請你看最後一句：以後，埃及必再有人居住。****神的審判，不是為了消滅，而是為了管教；連對埃及，神也留下一個「以後」。****這是整卷耶利米書，一個很有意思的細節：神是列國的主，祂的審判，仍然是有盼望的審判。**']),
dict(a=27,z=28,star=3,lit=L(27,28),
key=[('僕人','H5650','avdi','我的僕人'),('懼怕','H3372','tira','懼怕'),('拯救','H3467','moshiekha','拯救'),('平靖','H8252','veshaqat','平靜、安穩'),('安逸','H7599','veshaanan','安逸'),('懲治','H3256','yissarti','管教、懲治'),('滅絕','H3617','khalah','滅絕')],
gram=['**我的僕人雅各**：這是一個很溫柔的稱呼。**在埃及的預言中間，神忽然轉過頭，對雅各說話，叫他「我的僕人」。**','**懲治**：「從寬懲治你」。**原文的意思是「按公義管教你」。****神的管教，不是毀滅，是公義的、有限度的。**'],
exp=['二十七節，在一長串審判埃及的話之後，神忽然轉過頭：**我的僕人雅各啊，不要懼怕！以色列啊，不要驚惶！因我要從遠方拯救你，從被擄到之地拯救你的後裔。雅各必回來，得享平靖安逸，無人使他害怕。****請你看這個轉折：前面是「埃及」「埃及」，現在，是「我的僕人雅各」。****神的眼睛，沒有一刻離開祂的百姓。**','請你留意這兩個稱呼：**我的僕人雅各，以色列。****「雅各」，是他們的出身；「以色列」，是神給的名字。****神一次叫出這兩個名字，像是說：我記得你們從哪裡來，也記得我給你們的身分。****這是在被擄、在逃亡、在埃及的人們，心裡最需要聽見的一句話。**','二十八節，神重複這個呼召，又加上更多：**我的僕人雅各啊，不要懼怕！因我與你同在。我要將我所趕你到的那些國滅絕淨盡，卻不將你滅絕淨盡，倒要從寬懲治你，萬不能不罰你。這是耶和華說的。****請你注意：「因我與你同在」。****這是整個預言裡，最安靜、最溫柔的一句。**','這一節，也很誠實：**神說，我必不將你滅絕淨盡，卻也說，萬不能不罰你。****祂的安慰，不是廉價的；祂的管教，也不是殘酷的。****這是一個很完整的畫面：公義，與憐憫，同時存在。****我們不為這個應許，加上具體的時間，也不把它變成今日的政治預言；我們只看見：在列國的審判中，神給祂的百姓，留了一個「不要懼怕」。**']),
]
